import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const root = new Group();

  // Store cleanup callbacks
  const cleanupFns = [];

  // Load GLB mesh (if provided)
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
    });
  }

  // Apply cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const primitiveFn = ctx.primitives[prim.name];
      if (primitiveFn) {
        const result = primitiveFn(root, prim.params ?? {});
        if (result) {
          if (typeof result.cleanup === 'function') cleanupFns.push(result.cleanup);
          if (result.timeline && typeof result.timeline.kill === 'function') {
            cleanupFns.push(() => result.timeline.kill());
          }
        }
      }
    });
  }

  // Event handlers container
  const handlers = {};

  // Hover lift (rise‑in preset: y +0.15 units)
  handlers.hover = () => {
    const tl = gsap.timeline();
    tl.to(root.position, {
      y: '+=0.15',
      duration: 0.7,
      ease: 'power3.out',
    });
    cleanupFns.push(() => tl.kill());
  };

  // Click press‑down and emit navigation event
  handlers.click = () => {
    const tl = gsap.timeline();
    tl.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    cleanupFns.push(() => tl.kill());
    ctx.emit('hub-home.select', {});
  };

  // Attach handlers to userData
  root.userData.handlers = handlers;

  // Cleanup routine
  root.userData.cleanup = () => {
    cleanupFns.forEach((fn) => {
      if (typeof fn === 'function') fn();
    });
  };

  return root;
}
